def reach(starts):
    seen = [[False] * w for _ in range(h)]
    stack = list(starts)
    for x, y in starts:
        seen[x][y] = True
    while stack:
        x, y = stack.pop()
        for a, b in neighbours(x, y):
            if inside(a, b) and not seen[a][b] and heights[a][b] >= heights[x][y]:
                seen[a][b] = True              # water here flows down to (x, y)
                stack.append((a, b))
    return seen

pacific = reach(cells in the first row and column)
atlantic = reach(cells in the last row and column)
